mapper.select:

 del_flag = '0'
     and teacher_id = #{teacherId}
     and teacher_name like concat('%', #{teacherName}, '%')
     and status = #{status}

order by teacher_id

select u.user_id as teacher_id, coalesce(nullif(trim(u.user_name), ''), u.nick_name) as teacher_name, c.config_id, c.base_salary, c.rate_primary_class, c.rate_jh_class, c.rate_primary_1on1, c.rate_junior_1on1, c.rate_senior_1on1, c.class_hours_per_session, c.commission_amount, c.status, c.del_flag, c.create_by, c.create_time, c.update_by, c.update_time, c.remark, (select count(distinct s.course_class_name) from edu_course_schedule s where s.teacher_id = u.user_id and s.del_flag = '0' and s.status = '0' and s.term_name in ('寒假', '春季') and s.class_mode = '1' and s.grade_name not in ('初一','初二','初三','高一','高二','高三')) as primary_class_count, (select count(distinct s.course_class_name) from edu_course_schedule s where s.teacher_id = u.user_id and s.del_flag = '0' and s.status = '0' and s.term_name in ('寒假', '春季') and s.class_mode = '1' and s.grade_name in ('初一','初二','初三','高一','高二','高三')) as jh_class_count, (select count(distinct s.course_class_name) from edu_course_schedule s where s.teacher_id = u.user_id and s.del_flag = '0' and s.status = '0' and s.term_name in ('寒假', '春季') and s.class_mode = '2') as one_on_one_class_count from sys_user u inner join sys_user_role ur on ur.user_id = u.user_id inner join sys_role r on r.role_id = ur.role_id and r.role_key = 'teacher' and r.status = '0' left join edu_teacher_salary_config c on c.teacher_id = u.user_id and c.del_flag = '0' u.del_flag = '0' and u.status = '0' and u.user_id = #{teacherId}
and (u.user_name like concat('%', #{teacherName}, '%') or u.nick_name like concat('%', #{teacherName}, '%'))
order by u.user_id

mapper.update:
update edu_teacher_salary_config
teacher_id = #{teacherId}, teacher_name = #{teacherName}, base_salary = #{baseSalary}, rate_primary_class = #{ratePrimaryClass}, rate_jh_class = #{rateJhClass}, rate_primary_1on1 = #{ratePrimary1on1}, rate_junior_1on1 = #{rateJunior1on1}, rate_senior_1on1 = #{rateSenior1on1}, class_hours_per_session = #{classHoursPerSession}, commission_amount = #{commissionAmount}, status = #{status}, del_flag = #{delFlag}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate(),
where config_id = #{configId}
